<script setup lang="ts">import type{Batch}from '../types/domain';defineProps<{modelValue:number;items:Batch[]}>();const emit=defineEmits(['update:modelValue']);const changed=(e:Event)=>emit('update:modelValue',Number((e.target as HTMLSelectElement).value));</script><template><label class="batch-select">样本批次<select :value="modelValue" @change="changed"><option v-for="b in items" :key="b.id" :value="b.id">{{b.name}} / {{b.sample_count}}条</option></select></label></template>
